else:
    tonguoc = 1
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            tonguoc += i
            if i != n // i:
                tonguoc += n // i
    if tonguoc == n:
        print('true')
    else:
        print('false')

