# Nhập số n
try:
    n = int(input())

    # Số hoàn hảo phải lớn hơn 1 (Số 1 không phải số hoàn hảo)
    if n <= 1:
        print("false")
    else:
        # Bắt đầu tổng = 1 (vì mọi số > 1 đều chia hết cho 1)
        tong_uoc = 1

        # Chỉ chạy vòng lặp từ 2 đến căn bậc hai của n
        # int(n ** 0.5) là lấy căn bậc 2
        can_bac_hai = int(n ** 0.5)

        for i in range(2, can_bac_hai + 1):
            if n % i == 0:
                tong_uoc += i # Cộng ước thứ nhất

                # Cộng ước thứ hai (nếu 2 ước khác nhau)
                # Ví dụ n=36, i=6 thì n//i=6. Chỉ cộng một lần số 6.
                # Ví dụ n=12, i=2 thì n//i=6. Cộng cả 2 và 6.
                if i != (n // i):
                    tong_uoc += (n // i)

        if tong_uoc == n:
            print("true")
        else:
            print("false")

except ValueError:
    print("false")

